<?php require_once __DIR__.'/config/db.php';if(!empty($_SESSION['user_id'])) redirect('account.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){$error='Use a valid name/email and a password of at least 8 characters.';}else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password,phone,role) VALUES(?,?,?,?,"customer")');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone]);$_SESSION['user_id']=(int)$pdo->lastInsertId();session_regenerate_id(true);redirect('account.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'This email is already registered.':'Registration failed.';}}}$page_title='Register — MediNova';require __DIR__.'/includes/store_header.php';?><section class="form-page"><div class="form-shell"><p class="kicker">CUSTOMER ACCOUNT</p><h1>Create account.</h1><?php if($error):?><div class="admin-alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Full name</label><input name="name" required></div><div class="form-row"><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Phone</label><input name="phone" required></div></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><button class="btn btn-light">Create account ↗</button></form></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
